import { useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useGetCmmntyManageQuery } from '~/entities/community/api/use-get-cmmnty-manage-query';
import { useNoticeListInfiniteQuery } from '~/entities/community/api/use-notice-list-infinite-query';
import { parseToDate } from '~/shared/lib/web-view-bridge';

export const NoticeDetailPage = () => {
  const { nttManageId } = useParams();
  const { data, isLoading } = useGetCmmntyManageQuery(nttManageId ?? '');
  const { markAsRead } = useNoticeListInfiniteQuery({});

  useEffect(() => {
    if (nttManageId && data) {
      markAsRead(nttManageId);
    }
  }, [data, nttManageId, markAsRead]);

  return (
    <div className="content sub">
      {isLoading && <FullScreenLoading />}
      <div className="board-view">
        <div className="border-view-top">
          <h3>{data?.tbCmmntyMastr?.nttSj}</h3>
          <span>{parseToDate(data?.tbCmmntyMastr?.registDt, 'yyyy.MM.dd')}</span>
        </div>
        <div className="border-view-content">
          <p className="whitespace-pre-line break-words">{data?.tbCmmntyMastr?.nttCn ?? ''}</p>
        </div>
      </div>
    </div>
  );
};
